import{_ as a,o as e,c as r,a2 as l}from"./chunks/framework.CDU0sSpB.js";const m=JSON.parse('{"title":"第二阶段 · 日常内容工作","description":"从首批跨行业任务扩展到邮件、日历、文档、表格和网页。","frontmatter":{"title":"第二阶段 · 日常内容工作","description":"从首批跨行业任务扩展到邮件、日历、文档、表格和网页。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-2.md","filePath":"delivery/stage-2.md","lastUpdated":1794017073000}'),d={name:"delivery/stage-2.md"};function h(i,t,o,s,n,c){return e(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="第二阶段-·-日常内容工作" tabindex="-1">第二阶段 · 日常内容工作 <a class="header-anchor" href="#第二阶段-·-日常内容工作" aria-label="Permalink to &quot;第二阶段 · 日常内容工作&quot;">​</a></h1><p>当前实现、已验证范围和明确留空项见<a href="/hearth-os/delivery/status.html">阶段二至六交付状态</a>。</p><h2 id="当前状态" tabindex="-1">当前状态 <a class="header-anchor" href="#当前状态" aria-label="Permalink to &quot;当前状态&quot;">​</a></h2><ul><li><strong>已实现代码闭环：</strong> 本地文件、知识库和公开网页来源，TXT、Markdown、CSV、JSON、HTML、PDF、DOCX、XLSX 提取，以及“草稿 → 审批 → 本地发件箱写入 → 回执”。</li><li><strong>仍未完成：</strong> 邮件和日历账户接入、真实发送或外部系统写入，以及 10–15 个真实日常任务验收。逐项证据见<a href="/hearth-os/delivery/status.html">阶段二至六交付状态</a>。</li></ul><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>第二阶段把 Hearth 从第一阶段的首批跨行业任务扩展到大多数日常内容工作：读取邮件、日历、文件和知识库，处理文档、表格和网页资料，起草内容，并在审批后发送或写入。顺序必须是先只读、再起草、最后才执行外部写入。</p><p>本阶段分为四个小阶段：</p><table tabindex="0"><thead><tr><th>小阶段</th><th>目标</th></tr></thead><tbody><tr><td><a href="/hearth-os/delivery/stage-2/2-1.html">2.1 接入只读信息源</a></td><td>让用户看到系统读取了什么，以及来源是否可靠。</td></tr><tr><td><a href="/hearth-os/delivery/stage-2/2-2.html">2.2 处理文档、表格与网页资料</a></td><td>产出有来源、能核对、可继续使用的资料结果。</td></tr><tr><td><a href="/hearth-os/delivery/stage-2/2-3.html">2.3 起草、审批与外部写入</a></td><td>先草稿、再审批、最后只执行一次外部写入。</td></tr><tr><td><a href="/hearth-os/delivery/stage-2/2-4.html">2.4 验收日常内容工作</a></td><td>用真实日常任务证明更少时间、更高准确和可恢复。</td></tr></tbody></table><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><ol><li>先接入只读信息来源，让用户看到系统读到了什么。</li><li>再加入文档、表格和网页资料的处理与引用。</li><li>然后打通起草、审批和测试账户下的发送或写入。</li><li>最后用真实日常任务验收时间节省、结果准确和失败恢复。</li></ol>',10)])])}const p=a(d,[["render",h]]);export{m as __pageData,p as default};
